  kStatGid,
  kStatRdev,
  kStatSize,
  kStatBlockSize,
  kStatBlocks,
  kStatAtimeSeconds,
  kStatAtimeNanoseconds,
  kStatMtimeSeconds,
  kStatMtimeNanoseconds,
  kStatCtimeSeconds,
  kStatCtimeNanoseconds,
  kFsType,
  kFsBlockSize,
  kFsBlocks,
  kFsBlocksFree,
  kFsBlocksAvailable,
  kFsFiles,
  kFsFilesFree,
  kFsId0,
  kFsId1,
  kFsNameLength,
  kFsFragmentSize,
  kFsFlags,
  kFsSpare0,
  kFsSpare1,
  kFsSpare2,
  kFsSpare3,
  kWordCount
